s+='''
test('After Starter excludes the before-starter branch while retaining its source text and evidence',()=>{const i=index([flag('set','0x006A'),{...flag('unset','0x006A'),expression:{op:'flag',flagId:'0x006A',state:'unset'}}]),before={op:'all',args:[{op:'flag',flagId:'0x006A',state:'unset'},{op:'flag',flagId:'0x0964',state:'unset'}]},after={op:'all',args:[{op:'flag',flagId:'0x006A',state:'set'},{op:'unknown',reason:'Other source state remains unresolved.'}]};assert(!core.matchesSelection(i,['unset'],'set',before));assert(core.matchesSelection(i,['set'],'set',after));assert.equal(core.describe(before),'(Flag 0x006A unset AND Flag 0x0964 unset)');assert.deepEqual(core.selectionExpression(i,'set'),{op:'flag',flagId:'0x006A',state:'set'});});
test('negation and alternative paths are evaluated conservatively with unrelated state unknown',()=>{const i=index([flag('starter','0x006A')]),set={op:'flag',flagId:'0x006A',state:'set'},unset={...set,state:'unset'},unknown={op:'unknown',reason:'Native condition'};assert(!core.matchesSelection(i,['starter'],'starter',{op:'not',arg:set}));assert(core.matchesSelection(i,['starter'],'starter',{op:'any',args:[unset,unknown]}));assert(!core.matchesSelection(i,['starter'],'starter',{op:'all',args:[unset,unknown]}));});
test('before/after variable nodes retain their own exact state instead of sharing both branches',()=>{const i=index([0,1].map(value=>({id:'mom'+value,label:'Mom state',labelOrigin:'raw-id',expression:{op:'variable',variableId:'0x4106',compare:'eq',value}})));assert(core.matchesSelection(i,['mom0'],'mom0',i.conditions[0].expression));assert(!core.matchesSelection(i,['mom1','mom0'],'mom1',i.conditions[0].expression));assert(core.matchesSelection(i,['mom1'],'mom1',i.conditions[1].expression));});
test('explicit owner labels preserve an owner-defined clear-flag event',()=>{const i=index([{id:'clear',label:'After My Reviewed Event',labelOrigin:'owner',expression:{op:'flag',flagId:'0x006A',state:'unset'}}]);assert(core.matchesSelection(i,['clear'],'clear',i.conditions[0].expression));assert(!core.matchesSelection(i,['clear'],'clear',{op:'flag',flagId:'0x006A',state:'set'}));});
''';p.write_text(s,encoding='utf-8',newline='\n')
